-- City-specific curation for Isparta, İstanbul, İzmir and Karabük.
-- Inserts are idempotent by slug and city/name; no images are added.

UPDATE public.places SET latitude=38.297, longitude=31.185, short_description='Pisidia bölgesinin önemli antik kentlerinden; anıtsal yapıları ve erken Hristiyanlık mirasıyla tanınır.', long_description='Yalvaç yakınındaki Pisidia Antiokheia, Roma dönemi kent kalıntıları ve Aziz Pavlus ile ilişkilendirilen tarihî mirasıyla Isparta’nın önde gelen arkeolojik alanıdır.', source_url='https://isparta.ktb.gov.tr/TR-70972/kultur-turizmi.html', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='Isparta' AND slug='pisidia-antiokheia-antik-kenti';
UPDATE public.places SET latitude=38.296, longitude=31.178, short_description='Yalvaç ve çevresindeki arkeolojik buluntular ile bölgenin tarihini tanıtan müze.', long_description='Yalvaç Müzesi, Pisidia Antiokheia ve çevresinden gelen eserlerle bölgenin arkeolojik ve kültürel geçmişini tanıtır.', source_url='https://muze.gov.tr/muze-detay?DistId=YVM&SectionId=YVM01', verified=true, trust_score=90, content_review_status='source_backed', updated_at=now() WHERE city='Isparta' AND slug='yalvac-muzesi';

INSERT INTO public.places (name,category,city,address,latitude,longitude,slug,short_description,long_description,source_url,external_source,external_id,verified,trust_score,is_active,content_review_status,tags,updated_at)
SELECT s.name,s.category,s.city,s.address,s.latitude,s.longitude,s.slug,s.short_description,s.long_description,s.source_url,'curated_seed',s.slug,true,95,true,'source_backed',jsonb_build_array(s.category,s.city),now()
FROM (VALUES
('Galata Kulesi','Tarih ve mimari','İstanbul','Bereketzade, Beyoğlu',41.0256,28.9742,'istanbul-galata-kulesi','İstanbul siluetinin simgelerinden; tarihî kule ve şehir manzarası noktası.','Galata Kulesi, Beyoğlu’nda tarihî yarımada ve Boğaz çevresine bakan panoramik manzarasıyla öne çıkar. Ziyaret saatleri değişebileceğinden gitmeden önce resmî bilgileri kontrol edin.','https://istanbul.ktb.gov.tr/TR-309634/galata-kulesi.html'),
('İstanbul Arkeoloji Müzeleri','Müze ve kültür','İstanbul','Osman Hamdi Bey Yokuşu, Fatih',41.0115,28.9811,'istanbul-arkeoloji-muzeleri','Farklı uygarlıklara ait arkeolojik eserleri bir araya getiren müze kompleksi.','İstanbul Arkeoloji Müzeleri, antik çağlardan farklı dönemlere uzanan arkeolojik koleksiyonlarıyla kentin başlıca kültür duraklarındandır.','https://istanbul.ktb.gov.tr/TR-276860/mudurlugumuze-bagli-muzeler.html'),
('Kız Kulesi','Tarih ve mimari','İstanbul','Salacak açıkları, Üsküdar',41.0211,29.0041,'istanbul-kiz-kulesi','Boğaz girişinde küçük bir ada üzerinde yer alan tarihî kule.','Kız Kulesi, İstanbul Boğazı’nın simge yapılarından biridir. Ulaşım ve ziyaret düzeni için güncel resmî duyurular kontrol edilmelidir.','https://istanbul.ktb.gov.tr/TR-276795/gezilecek-yerler.html'),
('Ayasofya Tarih ve Deneyim Müzesi','Müze ve kültür','İstanbul','Soğukçeşme Sokak, Fatih',41.0087,28.9792,'istanbul-ayasofya-tarih-deneyim-muzesi','Ayasofya’nın tarihini ve mimari katmanlarını anlatan deneyim müzesi.','Ayasofya Tarih ve Deneyim Müzesi, yapının uzun tarihini ve farklı dönemlerini anlatan bir kültür durağıdır. Ziyaret düzeni için resmî bilgileri kontrol edin.','https://istanbul.ktb.gov.tr/TR-276860/mudurlugumuze-bagli-muzeler.html'),
('Rumeli Hisarı','Tarih ve mimari','İstanbul','Rumeli Hisarı, Sarıyer',41.0849,29.0564,'istanbul-rumeli-hisari','Boğaz’ın dar noktasında inşa edilmiş tarihî hisar.','Rumeli Hisarı, İstanbul Boğazı’nın kontrolü için inşa edilmiş tarihî savunma yapısıdır; surları ve konumuyla şehrin önemli miras alanları arasındadır.','https://istanbul.ktb.gov.tr/TR-276860/mudurlugumuze-bagli-muzeler.html')
) AS s(name,category,city,address,latitude,longitude,slug,short_description,long_description,source_url)
WHERE NOT EXISTS (SELECT 1 FROM public.places p WHERE p.slug=s.slug)
AND NOT EXISTS (SELECT 1 FROM public.places p WHERE p.city=s.city AND lower(trim(p.name))=lower(trim(s.name)));

UPDATE public.places SET short_description='İzmir Körfezi ve kent merkezine bakan konumuyla tarihî kale ve seyir noktası.', long_description='Kadifekale, İzmir merkezindeki tarihî savunma alanıdır; yüksek konumu kent ve körfez manzarasını izleme olanağı sunar.', source_url='https://izmir.ktb.gov.tr/TR-92447/kultur-turizmi.html', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='İzmir' AND slug='kadifekale';
UPDATE public.places SET short_description='Konak Meydanı’ndaki, 1901’de açılan ve İzmir’in simgesi hâline gelen Osmanlı dönemi saat kulesi.', long_description='İzmir Saat Kulesi, Konak Meydanı’nda 1901 yılında inşa edilmiş sekizgen planlı tarihî yapıdır. Meydan ve çevresindeki kent gezisinin başlıca duraklarındandır.', source_url='https://izmir.ktb.gov.tr/tr-77373/saat-kulesi.html', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='İzmir' AND slug='izmir-saat-kulesi';
UPDATE public.places SET is_active=false, content_review_status='rejected', updated_at=now() WHERE city='İzmir' AND slug='osm-node-1936293144' AND EXISTS(SELECT 1 FROM public.places p WHERE p.city='İzmir' AND p.slug='kadifekale' AND p.is_active=true);

