UPDATE public.places SET short_description='İncekaya Su Kemeri’nin üzerinden geçtiği, dik kireçtaşı yamaçlarıyla bilinen kanyon.', long_description='Tokatlı Kanyonu, Safranbolu çevresinde yürüyüş ve doğa gözlemi için bilinen bir doğal alandır. Rota ve geçiş koşulları ziyaret öncesinde kontrol edilmelidir.', source_url='https://karabuk.ktb.gov.tr/TR-63758/magara-ve-kanyonlar.html', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='Karabük' AND slug='tokatli-kanyonu';
UPDATE public.places SET short_description='Safranbolu’nun tarihî kentini ve çevresindeki geleneksel ev dokusunu yukarıdan izleme noktası.', long_description='Hıdırlık Tepesi, Safranbolu’nun tarihî evleri ve kent dokusunu gözlemlemek için kullanılan tanınmış seyir noktalarındandır.', source_url='https://karabuk.ktb.gov.tr/TR-63714/yapmadan-donme.html', verified=true, trust_score=90, content_review_status='source_backed', updated_at=now() WHERE city='Karabük' AND slug='hidirlik-tepesi-seyir-alani';
